// Package surface holds the route inventory of RealityEngine_CI's
// SURFACE_SPEC.md and answers every specified route this runtime does not
// implement with the specified 501 "unsupported" envelope.
//
// The inventory (spec-routes.json) is generated by cmd/refresh-surface from a
// committed SURFACE_SPEC.md, never edited by hand. Its schema, extraction
// rules and routesSha256 digest are the same as RealityEngine_Rust's
// conformance/surface/spec-routes.json, so the two can be compared directly.
package surface

import (
	"bufio"
	"bytes"
	"crypto/sha256"
	_ "embed"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"regexp"
	"strings"
	"unicode/utf16"
)

// Layers, as the inventory names them.
const (
	RE       = "RE"
	PE       = "PE"
	REPhase2 = "RE-phase2"
)

// Route is one row of a SURFACE_SPEC route table.
type Route struct {
	ID       string `json:"id"`
	Layer    string `json:"layer"`
	Group    string `json:"group"`
	Method   string `json:"method"`
	Path     string `json:"path"`
	SpecLine int    `json:"specLine"`
}

// Source pins the specification an inventory was taken from.
type Source struct {
	Repository string `json:"repository"`
	Path       string `json:"path"`
	Commit     string `json:"commit"`
	Sha256     string `json:"sha256"`
}

// Inventory is the content of spec-routes.json.
type Inventory struct {
	Schema       int            `json:"schema"`
	Purpose      string         `json:"purpose"`
	Source       Source         `json:"source"`
	Excluded     []string       `json:"excluded"`
	Counts       map[string]int `json:"counts"`
	RoutesSha256 string         `json:"routesSha256"`
	Routes       []Route        `json:"routes"`
}

// Purpose and Excluded are fixed text in every generated inventory.
const Purpose = "Route tables of SURFACE_SPEC.md; regenerate with go run ./cmd/refresh-surface, never by hand"

var Excluded = []string{"Manager (Visualizer) Surface: Manager's surface, not an engine's"}

// The sections taken, and the layer each becomes. The Manager section is
// Manager's surface, not an engine's, and is not taken.
var sectionLayers = map[string]string{
	"Reality Engine (RE) Surface":    RE,
	"Perception Engine (PE) Surface": PE,
	"K-lines and runtime snapshots":  REPhase2,
}

var (
	engineHeader = regexp.MustCompile(`^\|\s*(Method|Protocol)\s*\|\s*Path\s*\|\s*CPP\s*\|\s*LSP\s*\|\s*Scala\s*\|`)
	phase2Header = regexp.MustCompile(`^\|\s*Method\s*\|\s*Path\s*\|\s*Does\s*\|`)
	routeRow     = regexp.MustCompile("^\\|\\s*([A-Za-z]+)\\s*\\|\\s*`([^`]+)`\\s*\\|")
	protocols    = map[string]string{"SSE": "SSE", "WebSocket": "WS"}
)

// Parse extracts the engine route tables from SURFACE_SPEC.md:
//   - RE: every row of the RE section's `| Method | Path | CPP | LSP | Scala |`
//     and `| Protocol | Path | ... |` tables;
//   - PE: the same tables in the PE section;
//   - RE-phase2: the K-line snapshot routes, written outside those tables on
//     purpose (`| Method | Path | Does |`).
//
// It fails if the specification lists a route twice.
func Parse(spec []byte) ([]Route, error) {
	var routes []Route
	var section, group string
	table := false
	scanner := bufio.NewScanner(bytes.NewReader(spec))
	scanner.Buffer(make([]byte, 0, 1<<16), 1<<22)
	for number := 1; scanner.Scan(); number++ {
		line := scanner.Text()
		switch {
		case strings.HasPrefix(line, "## "):
			section, group, table = strings.TrimSpace(line[3:]), "", false
			continue
		case strings.HasPrefix(line, "### "):
			group, table = strings.TrimSpace(line[4:]), false
			continue
		}
		layer, ok := sectionLayers[section]
		if !ok {
			continue
		}
		if engineHeader.MatchString(line) || (layer == REPhase2 && phase2Header.MatchString(line)) {
			table = true
			continue
		}
		if !strings.HasPrefix(line, "|") {
			table = false
			continue
		}
		if !table {
			continue
		}
		if m := routeRow.FindStringSubmatch(line); m != nil {
			method, ok := protocols[m[1]]
			if !ok {
				method = strings.ToUpper(m[1])
			}
			routes = append(routes, Route{
				ID: layer + " " + method + " " + m[2], Layer: layer, Group: group,
				Method: method, Path: m[2], SpecLine: number,
			})
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, err
	}
	seen := map[string]bool{}
	var duplicates []string
	for _, r := range routes {
		if seen[r.ID] {
			duplicates = append(duplicates, r.ID)
		}
		seen[r.ID] = true
	}
	if len(duplicates) > 0 {
		return nil, fmt.Errorf("the spec lists a route twice: %v", duplicates)
	}
	return routes, nil
}

// Digest is the routesSha256 of a route list: SHA-256 over the canonical JSON
// of each route's id, layer, group, method and path. The canonical form is
// byte-identical to Python's json.dumps(rows, sort_keys=True,
// separators=(",", ":")), which RealityEngine_Rust uses: sorted keys, no
// spaces, no HTML escaping, and non-ASCII written as \uXXXX.
func Digest(routes []Route) (string, error) {
	type row struct {
		Group  string `json:"group"`
		ID     string `json:"id"`
		Layer  string `json:"layer"`
		Method string `json:"method"`
		Path   string `json:"path"`
	}
	rows := make([]row, len(routes))
	for i, r := range routes {
		rows[i] = row{r.Group, r.ID, r.Layer, r.Method, r.Path}
	}
	var buf bytes.Buffer
	encoder := json.NewEncoder(&buf)
	encoder.SetEscapeHTML(false)
	if err := encoder.Encode(rows); err != nil {
		return "", err
	}
	canonical := asciiEscape(bytes.TrimSuffix(buf.Bytes(), []byte("\n")))
	sum := sha256.Sum256(canonical)
	return hex.EncodeToString(sum[:]), nil
}

// asciiEscape writes every non-ASCII rune as \uXXXX (UTF-16 surrogate pairs
// above the BMP), as Python's ensure_ascii does. Go's encoder escapes U+2028
// and U+2029 itself; those already appear as   /  .
func asciiEscape(b []byte) []byte {
	var out bytes.Buffer
	for _, r := range string(b) {
		if r < 0x80 {
			out.WriteRune(r)
			continue
		}
		for _, unit := range utf16.Encode([]rune{r}) {
			fmt.Fprintf(&out, `\u%04x`, unit)
		}
	}
	return out.Bytes()
}

// Counts is the number of routes per layer.
func Counts(routes []Route) map[string]int {
	counts := map[string]int{RE: 0, PE: 0, REPhase2: 0}
	for _, r := range routes {
		counts[r.Layer]++
	}
	return counts
}

//go:embed spec-routes.json
var embedded []byte

// Load returns the vendored inventory, refusing one whose routes no longer
// match its digest (an inventory edited by hand).
func Load() (Inventory, error) {
	var inv Inventory
	if err := json.Unmarshal(embedded, &inv); err != nil {
		return inv, fmt.Errorf("spec-routes.json: %w", err)
	}
	digest, err := Digest(inv.Routes)
	if err != nil {
		return inv, err
	}
	if digest != inv.RoutesSha256 {
		return inv, fmt.Errorf("spec-routes.json does not match its routesSha256: edited by hand? regenerate with go run ./cmd/refresh-surface")
	}
	return inv, nil
}

// MustLoad is Load for program start-up and tests.
func MustLoad() Inventory {
	inv, err := Load()
	if err != nil {
		panic(err)
	}
	return inv
}
